(187, 1, '2025-12-12 18:00:16', '2025-12-12 11:00:16', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ผัดกระเพราหมูสับเต้าหู้-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ผัดกระเพราหมูสับเต้าหู้-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ผัดกระเพราหมูสับเต้าหู้-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ผัดกระเพราหมูสับเต้าหู้-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ผัดกระเพราหมูสับเต้าหู้-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>กะเพราหมูสับเต้าหู้</h2>		<p>กะเพราหมูสับเต้าหู้สูตรบ้าน ๆ หอมกลิ่นใบกะเพราสด ผัดกับหมูสับเนื้อนุ่มและเต้าหู้ชิ้นพอดีคำ ปรุงรสจัดจ้านด้วยพริกกระเทียมและซอสสูตรเฉพาะ รสเผ็ดกำลังดี กลมกล่อม อิ่มอร่อย ได้ทั้งโปรตีนและความอร่อยในจานเดียว</p>					\n						<details id=\"e-n-accordion-item-9490\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-9490\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>หมูสับ</li><li>ใบกระเพรา</li><li>พริก</li><li>กระเทียม </li><li>ซอสหอยนางรม </li><li>ซอสปรุงรส</li><li>น้ำตาล</li><li>เต้าหู้ไข่  หลอด </li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-9491\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-9491\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>628 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ อาหารจานเดียว</li></ul>								\n					</details>\n				<ul><li>หมูสับ</li><li>ใบกระเพรา</li><li>พริก</li><li>กระเทียม </li><li>ซอสหอยนางรม </li><li>ซอสปรุงรส</li><li>น้ำตาล</li><li>เต้าหู้ไข่  หลอด </li></ul><ul><li>628 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ อาหารจานเดียว</li></ul>					\n			บาท			\n				20', 'กะเพราหมูสับเต้าหู้', '', 'publish', 'closed', 'open', '', '%e0%b8%ad%e0%b8%b2%e0%b8%ab%e0%b8%b2%e0%b8%a3%e0%b8%88%e0%b8%b2%e0%b8%99%e0%b9%80%e0%b8%94%e0%b8%b5%e0%b8%a2%e0%b8%a7', '', '', '2026-01-09 11:02:27', '2026-01-09 04:02:27', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=187', 0, 'post', '', 0),
