(401, 1, '2025-12-21 09:29:50', '2025-12-21 02:29:50', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ข้าวผัดหมู-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ข้าวผัดหมู-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ข้าวผัดหมู-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ข้าวผัดหมู-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/12/ข้าวผัดหมู-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>ข้าวผัดหมู</h2>		<p data-start=\"236\" data-end=\"344\">ข้าวผัดหมูร้อน ๆ ผัดหอมกระทะ เม็ดข้าวร่วนไม่แฉะ หมูนุ่มชิ้นพอดีคำ ปรุงรสกลมกล่อม กินง่าย อิ่มอร่อยได้ทุกมื้อ</p>					\n						<details id=\"e-n-accordion-item-1810\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-1810\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>หมู</li><li>ข้าว</li><li>ซีอิ๊วข้าว</li><li>ไข่ไก่</li><li>กระเทียม</li><li>ต้นหอม</li><li>น้ำมันหอย</li><li>น้ำตาลเล็กน้อย</li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-1811\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-1811\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>520 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>								\n					</details>\n				<ul><li>หมู</li><li>ข้าว</li><li>ซีอิ๊วข้าว</li><li>ไข่ไก่</li><li>กระเทียม</li><li>ต้นหอม</li><li>น้ำมันหอย</li><li>น้ำตาลเล็กน้อย</li></ul><ul><li>520 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>					\n			บาท			\n				20', 'ข้าวผัดหมู', '', 'inherit', 'closed', 'closed', '', '381-revision-v1', '', '', '2025-12-21 09:29:50', '2025-12-21 02:29:50', '', 381, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=401', 0, 'revision', '', 0),
