(759, 1, '2026-01-07 19:55:32', '2026-01-07 12:55:32', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/650-กิโลแคลอรี่-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/650-กิโลแคลอรี่-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/650-กิโลแคลอรี่-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/650-กิโลแคลอรี่-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/650-กิโลแคลอรี่-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>สุกี้แห้งรวมมิตร</h2>		<p>รวมหมูนุ่ม กุ้ง และปลาหมึก ผัดไฟแรงกับวุ้นเส้นและผักสดจนหอมกลิ่นกระทะอันเป็นเอกลักษณ์ คลุกเคล้าซอสสุกี้สูตรเข้มข้นจนเข้าเนื้อ รสชาติจัดจ้านเครื่องแน่นอร่อยเต็มคำในจานเดียว</p>					\n						<details id=\"e-n-accordion-item-3590\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-3590\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li><p data-path-to-node=\"5,0,0\">เนื้อหมูหมัก, กุ้งสด และปลาหมึก</p></li><li><p data-path-to-node=\"5,1,0\">วุ้นเส้นสด</p></li><li><p data-path-to-node=\"5,2,0\">ผักกาดขาว, ผักบุ้ง และขึ้นฉ่าย</p></li><li><p data-path-to-node=\"5,3,0\">ไข่ไก่</p></li><li><p data-path-to-node=\"5,4,0\">ซอสสุกี้สูตรเข้มข้น</p></li><li><p data-path-to-node=\"5,5,0\">กระเทียมสับ</p></li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-3591\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-3591\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul style=\"font-size: 16px; font-style: normal; font-weight: 400;\"><li style=\"font-size: 16px;\">450 กิโลแคลอรี่</li><li style=\"font-size: 16px;\">เวลาในการเตรียม10-15 นาที</li><li style=\"font-size: 16px;\">หมวดหมู่ อาหารจานเดียว</li></ul>								\n					</details>\n				<ul><li><p data-path-to-node=\"5,0,0\">เนื้อหมูหมัก, กุ้งสด และปลาหมึก</p></li><li><p data-path-to-node=\"5,1,0\">วุ้นเส้นสด</p></li><li><p data-path-to-node=\"5,2,0\">ผักกาดขาว, ผักบุ้ง และขึ้นฉ่าย</p></li><li><p data-path-to-node=\"5,3,0\">ไข่ไก่</p></li><li><p data-path-to-node=\"5,4,0\">ซอสสุกี้สูตรเข้มข้น</p></li><li><p data-path-to-node=\"5,5,0\">กระเทียมสับ</p></li></ul><ul style=\"font-size: 16px; font-style: normal; font-weight: 400;\"><li style=\"font-size: 16px;\">450 กิโลแคลอรี่</li><li style=\"font-size: 16px;\">เวลาในการเตรียม10-15 นาที</li><li style=\"font-size: 16px;\">หมวดหมู่ อาหารจานเดียว</li></ul>					\n			บาท			\n				30', 'สุกี้แห้งรวมมิตร', '', 'trash', 'closed', 'open', '', '%e0%b8%aa%e0%b8%b8%e0%b8%81%e0%b8%b5%e0%b9%89%e0%b9%81%e0%b8%ab%e0%b9%89%e0%b8%87%e0%b8%a3%e0%