(783, 1, '2026-01-07 20:09:39', '2026-01-07 13:09:39', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/2-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/2-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/2-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/2-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/2-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>ผัดมาม่าขี้เมาทะเล</h2>		<p data-path-to-node=\"3\">เส้นบะหมี่เหนียวนุ่มผัดฉ่ากับกุ้งและปลาหมึกสด พร้อมเครื่องสมุนไพรและพริกกระเทียมจัดจ้าน รสชาติเผ็ดร้อนถึงใจ หอมกลิ่นใบกะเพราและกระชาย เสิร์ฟร้อนๆ อร่อยนัวสไตล์ขี้เมาทะเลแท้ๆ</p><p data-path-to-node=\"4\"> </p>					\n						<details id=\"e-n-accordion-item-2490\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-2490\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li><p data-path-to-node=\"5,0,0\">บะหมี่กึ่งสำเร็จรูป</p></li><li><p data-path-to-node=\"5,1,0\">กุ้งสด และ ปลาหมึก</p></li><li><p data-path-to-node=\"5,2,0\">พริกขี้หนูสดและกระเทียมบุบ</p></li><li><p data-path-to-node=\"5,3,0\">ใบกะเพรา, กระชาย, พริกไทยอ่อน และใบมะกรูด</p></li><li><p data-path-to-node=\"5,4,0\">ซอสปรุงรสเข้มข้น</p></li><li><p data-path-to-node=\"5,5,0\">ข้าวโพดอ่อน และถั่วฝักยาว</p></li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-2491\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-2491\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>520 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ อาหารจานเดียว</li></ul>								\n					</details>\n				<ul><li><p data-path-to-node=\"5,0,0\">บะหมี่กึ่งสำเร็จรูป</p></li><li><p data-path-to-node=\"5,1,0\">กุ้งสด และ ปลาหมึก</p></li><li><p data-path-to-node=\"5,2,0\">พริกขี้หนูสดและกระเทียมบุบ</p></li><li><p data-path-to-node=\"5,3,0\">ใบกะเพรา, กระชาย, พริกไทยอ่อน และใบมะกรูด</p></li><li><p data-path-to-node=\"5,4,0\">ซอสปรุงรสเข้มข้น</p></li><li><p data-path-to-node=\"5,5,0\">ข้าวโพดอ่อน และถั่วฝักยาว</p></li></ul><ul><li>520 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ อาหารจานเดียว</li></ul>					\n			บาท			\n				30', 'ผัดมาม่าขี้เมาทะเล', '', 'trash', 'closed', 'open', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%a1%e0%b8%b2%e0%b8%a1%e0%b9%88%e0%b8%b2%e0%b8%82%e0%b8%b5%e0%b9%89%e0%b9%80%e0%b8%a1%e0%b8%b2%e0%b8%97%e0%b8%b0%e0%b9%80%e0%b8%a5__trashed', '', '', '2026-01-16 08:49:21', '2026-01-16 01:49:21', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=783', 0, 'post', '', 0),
