(837, 1, '2026-01-07 20:46:18', '2026-01-07 13:46:18', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวเปล่า-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวเปล่า-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวเปล่า-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวเปล่า-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวเปล่า-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>ข้าวเปล่า</h2>		<p>ข้าวหอมมะลิคัดพิเศษหุงสุกใหม่ร้อนๆ เมล็ดเรียวยาวขาวสะอาด ให้เนื้อสัมผัสที่เหนียวนุ่มและมีกลิ่นหอมละมุนเป็นเอกลักษณ์ ทานคู่กับเมนูไหนก็อร่อย ช่วยชูรสชาติของกับข้าวให้โดดเด่นและทำให้อิ่มท้องได้อย่างลงตัว</p>					\n						<details id=\"e-n-accordion-item-2540\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-2540\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li><p data-path-to-node=\"5,0,0\">ข้าวหอมมะลิ 100%</p></li><li><p data-path-to-node=\"5,1,0\">หุงด้วยสัดส่วนน้ำที่พอเหมาะเพื่อให้ได้เมล็ดข้าวที่สวย ไม่แฉะ</p></li><li><p data-path-to-node=\"5,2,0\">เสิร์ฟร้อนๆ จากหม้อ</p></li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-2541\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-2541\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>150 กิโลแคลอรี่</li><li>เวลาในการเตรียม5 &#8211; 10นาที</li><li>หมวดหมู่ เพิ่มเติม</li></ul>								\n					</details>\n				<ul><li><p data-path-to-node=\"5,0,0\">ข้าวหอมมะลิ 100%</p></li><li><p data-path-to-node=\"5,1,0\">หุงด้วยสัดส่วนน้ำที่พอเหมาะเพื่อให้ได้เมล็ดข้าวที่สวย ไม่แฉะ</p></li><li><p data-path-to-node=\"5,2,0\">เสิร์ฟร้อนๆ จากหม้อ</p></li></ul><ul><li>150 กิโลแคลอรี่</li><li>เวลาในการเตรียม5 - 10นาที</li><li>หมวดหมู่ เพิ่มเติม</li></ul>					\n			บาท			\n				0', 'ข้าวเปล่า', '', 'trash', 'closed', 'open', '', '%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b9%80%e0%b8%9b%e0%b8%a5%e0%b9%88%e0%b8%b2__trashed', '', '', '2026-01-16 08:49:21', '2026-01-16 01:49:21', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=837', 0, 'post', '', 0),
