(1093, 1, '2026-01-09 12:21:58', '2026-01-09 05:21:58', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผงกะหรี่ไก่กรอบ-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผงกะหรี่ไก่กรอบ-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผงกะหรี่ไก่กรอบ-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผงกะหรี่ไก่กรอบ-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผงกะหรี่ไก่กรอบ-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>ผงกะหรี่ไก่กรอบ</h2>		<p data-path-to-node=\"3\">ไก่ชิ้นโตทอดกรอบนอกนุ่มใน ผัดเคลือบซอสผงกะหรี่สีทองรสละมุน หอมมันด้วยไข่และนมสด รสชาติกลมกล่อมเข้าเนื้อตัดกับความกรอบของไก่ได้อย่างลงตัว เสิร์ฟพร้อมข้าวสวยร้อนๆ</p><p data-path-to-node=\"4\"> </p>					\n						<details id=\"e-n-accordion-item-1800\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-1800\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li><p data-path-to-node=\"5,0,0\">เนื้อไก่ (ชุบแป้งทอดกรอบ)</p></li><li><p data-path-to-node=\"5,1,0\">ผงกะหรี่เกรดดี</p></li><li><p data-path-to-node=\"5,2,0\">ไข่ไก่และนมข้นจืด</p></li><li><p data-path-to-node=\"5,3,0\">หอมหัวใหญ่, ขึ้นฉ่าย และต้นหอม</p></li><li><p data-path-to-node=\"5,4,0\">น้ำมันน้ำพริกเผา</p></li><li><p data-path-to-node=\"5,5,0\">ข้าวสวย</p></li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-1801\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-1801\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>580 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>								\n					</details>\n				<ul><li><p data-path-to-node=\"5,0,0\">เนื้อไก่ (ชุบแป้งทอดกรอบ)</p></li><li><p data-path-to-node=\"5,1,0\">ผงกะหรี่เกรดดี</p></li><li><p data-path-to-node=\"5,2,0\">ไข่ไก่และนมข้นจืด</p></li><li><p data-path-to-node=\"5,3,0\">หอมหัวใหญ่, ขึ้นฉ่าย และต้นหอม</p></li><li><p data-path-to-node=\"5,4,0\">น้ำมันน้ำพริกเผา</p></li><li><p data-path-to-node=\"5,5,0\">ข้าวสวย</p></li></ul><ul><li>580 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>					\n			บาท			\n				25', 'ผงกะหรี่ไก่กรอบ', '', 'inherit', 'closed', 'closed', '', '698-revision-v1', '', '', '2026-01-09 12:21:58', '2026-01-09 05:21:58', '', 698, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1093', 0, 'revision', '', 0),
