(1133, 1, '2026-01-09 12:41:48', '2026-01-09 05:41:48', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผัดมาม่าหมู-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผัดมาม่าหมู-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผัดมาม่าหมู-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผัดมาม่าหมู-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ผัดมาม่าหมู-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>ผัดมาม่าหมู</h2>		<p>บะหมี่กึ่งสำเร็จรูปเส้นเหนียวนุ่มผัดไฟแรงคู่กับหมูหมักและผักสดจนเข้าเนื้อหอมกลิ่นกระทะ ปรุงรสจัดจ้านกลมกล่อมตามสูตรเฉพาะ เสิร์ฟร้อนๆ เป็นเมนูยอดฮิตที่อร่อยอิ่มท้องกำลังดี</p>					\n						<details id=\"e-n-accordion-item-1640\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-1640\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li><p data-path-to-node=\"5,0,0\">บะหมี่กึ่งสำเร็จรูป (ลวกสุกกำลังดี)</p></li><li><p data-path-to-node=\"5,1,0\">เนื้อหมูหมักนุ่ม</p></li><li><p data-path-to-node=\"5,2,0\">ผักคะน้า หรือกะหล่ำปลี</p></li><li><p data-path-to-node=\"5,3,0\">ไข่ไก่</p></li><li><p data-path-to-node=\"5,4,0\">ซอสปรุงรส และพริกขี้หนูสับ</p></li><li><p data-path-to-node=\"5,5,0\">กระเทียมสับหอม</p></li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-1641\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-1641\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>480 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>								\n					</details>\n				<ul><li><p data-path-to-node=\"5,0,0\">บะหมี่กึ่งสำเร็จรูป (ลวกสุกกำลังดี)</p></li><li><p data-path-to-node=\"5,1,0\">เนื้อหมูหมักนุ่ม</p></li><li><p data-path-to-node=\"5,2,0\">ผักคะน้า หรือกะหล่ำปลี</p></li><li><p data-path-to-node=\"5,3,0\">ไข่ไก่</p></li><li><p data-path-to-node=\"5,4,0\">ซอสปรุงรส และพริกขี้หนูสับ</p></li><li><p data-path-to-node=\"5,5,0\">กระเทียมสับหอม</p></li></ul><ul><li>480 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>					\n			บาท			\n				25', 'ผัดมาม่าหมู', '', 'inherit', 'closed', 'closed', '', '765-revision-v1', '', '', '2026-01-09 12:41:48', '2026-01-09 05:41:48', '', 765, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1133', 0, 'revision', '', 0);
