(1174, 1, '2026-01-09 12:52:34', '2026-01-09 05:52:34', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวไข่เจียวแหนม-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวไข่เจียวแหนม-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวไข่เจียวแหนม-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวไข่เจียวแหนม-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ข้าวไข่เจียวแหนม-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>ข้าวไข่เจียวแหนม</h2>		<p>ไข่เจียวฟูๆ คลุกเคล้ากับแหนมรสเปรี้ยวกำลังดี ทอดจนเหลืองกรอบและมีกลิ่นหอมที่เป็นเอกลักษณ์ รสสัมผัสหนึบหนับของเนื้อแหนมเข้ากันได้ดีกับไข่นุ่มๆ เสิร์ฟพร้อมข้าวสวยร้อนๆ อร่อยนัวครบรส</p>					\n						<details id=\"e-n-accordion-item-1010\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-1010\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul data-path-to-node=\"5\"><li><p data-path-to-node=\"5,0,0\">ไข่ไก่สด</p></li><li><p data-path-to-node=\"5,1,0\">แหนมหมูคุณภาพดี (ขยี้เป็นชิ้นพอดีคำ)</p></li><li><p data-path-to-node=\"5,2,0\">พริกขี้หนูซอย และหอมแดง (เพื่อความจัดจ้าน)</p></li><li><p data-path-to-node=\"5,3,0\">ซอสปรุงรสเพียงเล็กน้อย</p></li><li><p data-path-to-node=\"5,4,0\">ข้าวสวยหอมมะลินุ่มๆ</p></li><li><p data-path-to-node=\"5,5,0\">เครื่องเคียง: แตงกวา และพริกน้ำปลา</p></li></ul><p data-path-to-node=\"6\"> </p>								\n					</details>\n						<details id=\"e-n-accordion-item-1011\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-1011\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>530 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>								\n					</details>\n				<ul data-path-to-node=\"5\"><li><p data-path-to-node=\"5,0,0\">ไข่ไก่สด</p></li><li><p data-path-to-node=\"5,1,0\">แหนมหมูคุณภาพดี (ขยี้เป็นชิ้นพอดีคำ)</p></li><li><p data-path-to-node=\"5,2,0\">พริกขี้หนูซอย และหอมแดง (เพื่อความจัดจ้าน)</p></li><li><p data-path-to-node=\"5,3,0\">ซอสปรุงรสเพียงเล็กน้อย</p></li><li><p data-path-to-node=\"5,4,0\">ข้าวสวยหอมมะลินุ่มๆ</p></li><li><p data-path-to-node=\"5,5,0\">เครื่องเคียง: แตงกวา และพริกน้ำปลา</p></li></ul><p data-path-to-node=\"6\"> </p><ul><li>530 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>					\n			บาท			\n				25', 'ข้าวไข่เจียวแหนม', '', 'inherit', 'closed', 'closed', '', '825-revision-v1', '', '', '2026-01-09 12:52:34', '2026-01-09 05:52:34', '', 825, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1174', 0, 'revision', '', 0),
