(1283, 1, '2026-01-10 14:55:11', '2026-01-10 07:55:11', '<img class=\"alignnone size-full wp-image-850\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/ไข่ดาว-1.jpg\" alt=\"\" width=\"1024\" height=\"1024\" />jgk', 'ไข่ดาว', '', 'trash', 'open', 'closed', '', '%e0%b9%84%e0%b8%82%e0%b9%88%e0%b8%94%e0%b8%b2%e0%b8%a7__trashed', '', '', '2026-01-10 14:58:15', '2026-01-10 07:58:15', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1283', 0, 'product', '', 0),
