(1285, 1, '2026-01-10 15:07:40', '2026-01-10 08:07:40', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">200 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ เพิ่มเติม</span></li>\r\n</ul>', 'ไข่เจียว', 'ไข่ไก่สดตีจนขึ้นฟองละเอียด ปรุงรสกลมกล่อม ทอดในน้ำมันร้อนๆ จนขอบกรอบเหลืองทองและเนื้อในนุ่มฟู ส่งกลิ่นหอมฟุ้งเย้ายวนใจ จะทานเปล่าๆ หรือทานคู่กับซอสพริกและน้ำปลาพริกก็อร่อยลงตัว\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ไข่ไก่สด (แนะนำ 2-3 ฟองสำหรับ 1 จานกลาง)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">ซอสปรุงรส, น้ำปลา และพริกไทย</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">ต้นหอมซอย (เพิ่มสีสันและกลิ่นหอม)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">น้ำมันสำหรับทอด (ใช้ไฟแรงให้ขอบกรอบ)</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b9%84%e0%b8%82%e0%b9%88%e0%b9%80%e0%b8%88%e0%b8%b5%e0%b8%a2%e0%b8%a7', '', '', '2026-01-11 20:35:29', '2026-01-11 13:35:29', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1285', 0, 'product', '', 0);
