(1301, 1, '2026-01-10 15:44:23', '2026-01-10 08:44:23', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">520 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดมาม่าขี้เมาทะเล', 'เส้นบะหมี่เหนียวนุ่มผัดฉ่ากับกุ้งและปลาหมึกสด พร้อมเครื่องสมุนไพรและพริกกระเทียมจัดจ้าน รสชาติเผ็ดร้อนถึงใจ หอมกลิ่นใบกะเพราและกระชาย เสิร์ฟร้อนๆ อร่อยนัวสไตล์ขี้เมาทะเลแท้ๆ\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">บะหมี่กึ่งสำเร็จรูป</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">กุ้งสด และ ปลาหมึก</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">พริกขี้หนูสดและกระเทียมบุบ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ใบกะเพรา, กระชาย, พริกไทยอ่อน และใบมะกรูด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ซอสปรุงรสเข้มข้น</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,5,0\">ข้าวโพดอ่อน และถั่วฝักยาว</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%a1%e0%b8%b2%e0%b8%a1%e0%b9%88%e0%b8%b2%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%89%e0%b9%88%e0%b8%b2%e0%b8%97%e0%b8%b0%e0%b9%80%e0%b8%a5', '', '', '2026-01-16 09:28:02', '2026-01-16 02:28:02', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1301', 0, 'product', '', 0),
(1302, 1, '2026-01-10 15:51:04', '2026-01-10 08:51:04', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">700 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>\r\n&nbsp;', 'กะเพรากุนเชียง', 'กะเพรากุนเชียงรสจัดจ้าน ใช้กุนเชียงหอมหวานหั่นชิ้นพอดีคำ ผัดกับพริกกระเทียมและใบกะเพราสด ปรุงรสเข้มข้น หวานเค็มเผ็ดกลมกล่อม อร่อยลงตัวในสไตล์ไทย ๆ ทานกับข้าวสวยร้อน ๆ ยิ่งฟิน\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li data-start=\"349\" data-end=\"361\">\r\n<p data-start=\"351\" data-end=\"361\">กุนเชียง</p>\r\n</li>\r\n 	<li data-start=\"362\" data-end=\"374\">\r\n<p data-start=\"364\" data-end=\"374\">ใบกะเพรา</p>\r\n</li>\r\n 	<li data-start=\"375\" data-end=\"383\">\r\n<p data-start=\"377\" data-end=\"383\">พริก</p>\r\n</li>\r\n 	<li data-start=\"384\" data-end=\"396\">\r\n<p data-start=\"386\" data-end=\"396\">กระเทียม</p>\r\n</li>\r\n 	<li data-start=\"397\" data-end=\"410\">\r\n<p data-start=\"399\" data-end=\"410\">ซอสปรุงรส</p>\r\n</li>\r\n 	<li data-start=\"411\" data-end=\"421\">\r\n<p data-start=\"413\" data-end=\"421\">น้ำปลา</p>\r\n</li>\r\n 	<li data-start=\"422\" data-end=\"435\">\r\n<p data-start=\"424\" data-end=\"435\">น้ำมันพืช</p>\r\n</li>\r\n 	<li data-start=\"436\" data-end=\"445\">\r\n<p data-start=\"438\" data-end=\"445\">ข้าวสวย</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%81%e0%b8%b0%e0%b9%80%e0%b8%9e%e0%b8%a3%e0%b8%b2%e0%b8%81%e0%b8%b8%e0%b8%99%e0%b9%80%e0%b8%8a%e0%b8%b5%e0%b8%a2%e0%b8%87', '', '', '2026-01-16 09:27:57', '2026-01-16 02:27:57', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1302', 0, 'product', '', 0),
(1303, 1, '2026-01-10 15:52:36', '2026-01-10 08:52:36', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">แคลอรี่ 166</span><span class=\"font-medium\"> กิโลแคลอรี่</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'หมูกรอบทอดกระเทียม', 'ข้าวผัดกะเพราหมูกรอบสูตรต้นตำรับ ปรุงจากหมูสับสดใหม่คุณภาพดี ผัดร้อนๆ กับใบกะเพราสดหอมกรุ่น ปรุงรสด้วยพริกสด กระเทียม และซอสปรุงรสแบบไทยแท้ รสชาติกลมกล่อม เผ็ดร้อนกำลังดี\r\n<strong>ส่วนผสม\r\n</strong>\r\n<ul>\r\n 	<li><span class=\"inline-flex items-center justify-center rounded-md border px-2 py-0.5 text-xs font-medium w-fit whitespace-nowrap shrink-0 [&amp;&gt;svg]:size-3 gap-1 [&amp;&gt;svg]:pointer-events-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive transition-[color,box-shadow] overflow-hidden border-transparent bg-secondary text-secondary-foreground [a&amp;]:hover:bg-secondary/90\" data-slot=\"badge\">หมูกรอบ</span></li>\r\n 	<li><span class=\"inline-flex items-center justify-center rounded-md border px-2 py-0.5 text-xs font-medium w-fit whitespace-nowrap shrink-0 [&amp;&gt;svg]:size-3 gap-1 [&amp;&gt;svg]:pointer-events-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive transition-[color,box-shadow] overflow-hidden border-transparent bg-secondary text-secondary-foreground [a&amp;]:hover:bg-secondary/90\" data-slot=\"badge\">กระเทียม</span></li>\r\n 	<li>ซอสซีอี๊วขาว</li>\r\n 	<li>ผงปรุงรส</li>\r\n</ul>\r\n<strong> </strong>', 'publish', 'closed', 'closed', '', '%e0%b8%ab%e0%b8%a1%e0%b8%b9%e0%b8%81%e0%b8%a3%e0%b8%ad%e0%b8%9a%e0%b8%97%e0%b8%ad%e0%b8%94%e0%b8%81%e0%b8%a3%e0%b8%b0%e0%b9%80%e0%b8%97%e0%b8%b5%e0%b8%a2%e0%b8%a1', '', '', '2026-01-16 09:27:55', '2026-01-16 02:27:55', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1303', 0, 'product', '', 0),
(1304, 1, '2026-01-10 15:54:26', '2026-01-10 08:54:26', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">450 – 520 กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดพริกเเกงปลาดอลลี่', '<b data-path-to-node=\"4,0\" data-index-in-node=\"0\">“อร่อยนุ่ม… ละลายในปาก! พริกแกงปลาดอลลี่”</b> เอาใจคนรักสุขภาพกับเนื้อปลาดอลลี่สีขาวนวล นุ่มเด้ง ผัดคลุกเคล้ากับพริกแกงเผ็ดร้อนกำลังดี รสชาติกลมกล่อม หอมกลิ่นสมุนไพรแบบเน้นๆ ทานง่าย สบายท้อง ได้โปรตีนเน้นๆ จากเนื้อปลา\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>ปลาดอลลี่</li>\r\n 	<li>ถั่วฝักยาว</li>\r\n 	<li>พริกแกงเผ็ด</li>\r\n 	<li>ใบมะกรูด</li>\r\n 	<li>พริกชี้ฟ้าเเดง</li>\r\n 	<li>เครื่องปรุงรส (น้ำปลา, น้ำตาลปี๊บ)</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%9e%e0%b8%a3%e0%b8%b4%e0%b8%81%e0%b9%80%e0%b9%80%e0%b8%81%e0%b8%87%e0%b8%9b%e0%b8%a5%e0%b8%b2%e0%b8%94%e0%b8%ad%e0%b8%a5%e0%b8%a5%e0%b8%b5%e0%b9%88', '', '', '2026-01-16 09:24:18', '2026-01-16 02:24:18', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1304', 0, 'product', '', 0),
(1305, 1, '2026-01-10 15:55:21', '2026-01-10 08:55:21', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">580 – 680 กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดพริกเเกงคอหมูย่าง', '<b data-path-to-node=\"4,0\" data-index-in-node=\"0\">“หอมกลิ่นย่าง… ถึงเครื่องพริกแกง! ข้าวผัดพริกแกงคอหมูย่าง”</b> เปลี่ยนเมนูพริกแกงเดิมๆ ให้พิเศษกว่าเดิม ด้วยคอหมูย่างเนื้อนุ่มแทรกมันนิดๆ ย่างจนหอมกรุ่น นำมาผัดคลุกเคล้ากับพริกแกงสูตรเข้มข้น รสชาติเข้าเนื้อ หอมฟุ้งทุกคำที่เคี้ยว!\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>คอหมูย่าง</li>\r\n 	<li>ถั่วฝักยาว</li>\r\n 	<li>พริกแกงเผ็ด</li>\r\n 	<li>ใบมะกรูด</li>\r\n 	<li>พริกชี้ฟ้าเเดง</li>\r\n 	<li>เครื่องปรุงรส (น้ำปลา, น้ำตาลปี๊บ)</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%9e%e0%b8%a3%e0%b8%b4%e0%b8%81%e0%b9%80%e0%b9%80%e0%b8%81%e0%b8%87%e0%b8%ab%e0%b8%a1%e0%b8%b9%e0%b8%aa%e0%b8%b2%e0%b8%a1%e0%b8%8a%e0%b8%b1%e0%b9%89%e0%b8%99', '', '', '2026-01-16 09:24:22', '2026-01-16 02:24:22', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1305', 0, 'product', '', 0),
(1306, 1, '2026-01-10 15:56:24', '2026-01-10 08:56:24', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">550-750 กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดพริกเเกงหมูสามชั้น', 'หมูสามชั้นคัดชั้นสวยๆ เนื้อนุ่มมันแทรกกำลังดี ผัดจนน้ำพริกแกงซึมเข้าเนื้อ รสชาติเข้มข้น หอมกลิ่นสมุนไพรไทยแท้ ตักทานกับข้าวสวยร้อนๆ บอกเลยว่า “ฟิน” จนคำสุดท้าย\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>หมูสามชั้น</li>\r\n 	<li>ถั่วฝักยาว</li>\r\n 	<li>พริกแกงเผ็ด</li>\r\n 	<li>ใบมะกรูด</li>\r\n 	<li>พริกชี้ฟ้าเเดง</li>\r\n 	<li>เครื่องปรุงรส (น้ำปลา, น้ำตาลปี๊บ)</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%9e%e0%b8%a3%e0%b8%b4%e0%b8%81%e0%b9%80%e0%b9%80%e0%b8%81%e0%b8%87%e0%b8%ab%e0%b8%a1%e0%b8%b9%e0%b8%aa%e0%b8%b2%e0%b8%a1%e0%b8%8a%e0%b8%b1%e0%b9%89%e0%b8%99-2', '', '', '2026-01-16 09:24:24', '2026-01-16 02:24:24', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1306', 0, 'product', '', 0),
(1307, 1, '2026-01-10 15:58:02', '2026-01-10 08:58:02', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">550-750 กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดพริกเเกงหมูกรอบ', 'หมูกรอบชิ้นโต ผัดพริกแกงเข้มข้น รสชาติกลมกล่อม หอมเครื่องเทศไทยแท้ เลือกความเผ็ดได้ตามใจคุณ\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>หมูกรอบ</li>\r\n 	<li>ถั่วฝักยาว</li>\r\n 	<li>พริกแกงเผ็ด</li>\r\n 	<li>ใบมะกรูด</li>\r\n 	<li>พริกชี้ฟ้าเเดง</li>\r\n 	<li>เครื่องปรุงรส (น้ำปลา, น้ำตาลปี๊บ)</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%9e%e0%b8%a3%e0%b8%b4%e0%b8%81%e0%b9%80%e0%b9%80%e0%b8%81%e0%b8%87%e0%b8%ab%e0%b8%a1%e0%b8%b9%e0%b8%81%e0%b8%a3%e0%b8%ad%e0%b8%9a', '', '', '2026-01-16 09:24:28', '2026-01-16 02:24:28', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1307', 0, 'product', '', 0);
