(1312, 1, '2026-01-10 16:04:11', '2026-01-10 09:04:11', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">530 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ข้าวไข่เจียวเเหนม', 'ไข่เจียวฟูๆ คลุกเคล้ากับแหนมรสเปรี้ยวกำลังดี ทอดจนเหลืองกรอบและมีกลิ่นหอมที่เป็นเอกลักษณ์ รสสัมผัสหนึบหนับของเนื้อแหนมเข้ากันได้ดีกับไข่นุ่มๆ เสิร์ฟพร้อมข้าวสวยร้อนๆ อร่อยนัวครบรส\r\n\r\n<strong>ส่วนผสม</strong>\r\n<ul data-path-to-node=\"5\">\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ไข่ไก่สด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">แหนมหมูคุณภาพดี (ขยี้เป็นชิ้นพอดีคำ)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">พริกขี้หนูซอย และหอมแดง (เพื่อความจัดจ้าน)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ซอสปรุงรสเพียงเล็กน้อย</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวยหอมมะลินุ่มๆ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,5,0\">เครื่องเคียง: แตงกวา และพริกน้ำปลา</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b9%84%e0%b8%82%e0%b9%88%e0%b9%80%e0%b8%88%e0%b8%b5%e0%b8%a2%e0%b8%a7%e0%b9%80%e0%b9%80%e0%b8%ab%e0%b8%99%e0%b8%a1', '', '', '2026-01-16 09:20:22', '2026-01-16 02:20:22', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1312', 0, 'product', '', 0),
