(1314, 1, '2026-01-10 16:05:12', '2026-01-10 09:05:12', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">520 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ข้าวไข่เจียวบีลัคกี้', 'ไข่ไก่สดตีผสมกับโบโลน่าบีลัคกี้หั่นชิ้น ทอดจนเหลืองทองฟูฟ่องหอมกลิ่นรมควันอันเป็นเอกลักษณ์ เนื้อสัมผัสนุ่มเด้งของโบโลน่าเข้ากันได้ดีกับไข่เจียวรสกลมกล่อม เสิร์ฟบนข้าวสวยร้อนๆ อร่อยฟินกินเพลิน\r\n\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ไข่ไก่สด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">โบโลน่าบีลัคกี้ (Belucky Bologna)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">ซอสปรุงรสและน้ำปลาแท้</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ต้นหอมซอย</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวยหอมมะลินุ่มๆ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,5,0\">ซอสพริกหรือซอสมะเขือเทศ</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b9%84%e0%b8%82%e0%b9%88%e0%b9%80%e0%b8%88%e0%b8%b5%e0%b8%a2%e0%b8%a7%e0%b8%9a%e0%b8%b5%e0%b8%a5%e0%b8%b1%e0%b8%84%e0%b8%81%e0%b8%b5%e0%b9%89', '', '', '2026-01-16 09:20:20', '2026-01-16 02:20:20', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1314', 0, 'product', '', 0),
(1315, 1, '2026-01-10 16:06:33', '2026-01-10 09:06:33', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">500 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ข้าวไข่เจียวหมูสับ', 'ไข่ไก่สดตีผสมหมูสับจนเข้ากัน ทอดในกระทะร้อนๆ จนเหลืองทองฟูฟ่องและหอมกรุ่นทั่วจาน เนื้อสัมผัสนุ่มในกรอบนอก รสชาติกลมกล่อมลงตัว เสิร์ฟบนข้าวสวยร้อนๆ อร่อยง่ายแต่ฟินไม่รู้ลืม\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ไข่ไก่สด (2-3 ฟอง)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">เนื้อหมูสับละเอียด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">ซอสปรุงรสและน้ำปลาแท้</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ต้นหอมซอย (ตามชอบ)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวยหอมมะลินุ่มๆ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,5,0\">ซอสพริกหรือน้ำปลาพริก</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b9%84%e0%b8%82%e0%b9%88%e0%b9%80%e0%b8%88%e0%b8%b5%e0%b8%a2%e0%b8%a7', '', '', '2026-01-16 09:16:25', '2026-01-16 02:16:25', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1315', 0, 'product', '', 0),
(1316, 1, '2026-01-10 16:07:32', '2026-01-10 09:07:32', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">300 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ข้าวต้มทะเล', 'ข้าวหอมมะลิต้มสุกกำลังดีในน้ำซุปใสรสกลมกล่อม จัดเต็มด้วยกุ้งและปลาหมึกสดเนื้อเด้งหวาน หอมกลิ่นขิงซอยและขึ้นฉ่าย เสิร์ฟร้อนๆ อร่อยสดชื่นได้รสสัมผัสจากทะเลแท้ๆ ในทุกคำ\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ข้าวหอมมะลิต้ม</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">กุ้งสด และ ปลาหมึกสด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">น้ำซุปโครงไก่หรือซุปซีฟู้ดรสเชี่ยว</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ขิงซอย, ขึ้นฉ่าย และต้นหอม</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">กระเทียมเจียวและตังฉ่าย</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,5,0\">พริกไทยป่น</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b8%95%e0%b9%89%e0%b8%a1%e0%b8%97%e0%b8%b0%e0%b9%80%e0%b8%a5', '', '', '2026-01-16 09:16:22', '2026-01-16 02:16:22', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1316', 0, 'product', '', 0),
