(1320, 1, '2026-01-10 16:12:07', '2026-01-10 09:12:07', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">500 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดมาม่าขี้เมาหมู', 'เส้นบะหมี่เหนียวนุ่มผัดสมุนไพรสดและพริกกระเทียมจนหอมฟุ้ง คลุกเคล้าหมูหมักรสเข้มข้น รสชาติเผ็ดร้อนจัดจ้านสไตล์ขี้เมาแท้ๆ เสิร์ฟร้อนๆ พร้อมใบกะเพราหอมกรุ่นทุกคำที่สัมผัส\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">บะหมี่กึ่งสำเร็จรูป</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">เนื้อหมูหมักนุ่ม</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">พริกขี้หนูและกระเทียมบุบ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ใบกะเพรา, พริกไทยอ่อน และกระชาย</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ซอสปรุงรสสูตรขี้เมา</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,5,0\">ผักสดตามชอบ (ข้าวโพดอ่อน, ถั่วฝักยาว)</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%a1%e0%b8%b2%e0%b8%a1%e0%b9%88%e0%b8%b2%e0%b8%82%e0%b8%b5%e0%b9%89%e0%b9%80%e0%b8%a1%e0%b8%b2%e0%b8%ab%e0%b8%a1%e0%b8%b9', '', '', '2026-01-16 09:12:21', '2026-01-16 02:12:21', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1320', 0, 'product', '', 0),
