(1336, 1, '2026-01-10 16:26:23', '2026-01-10 09:26:23', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">460 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดผักบุ้งทะเล', 'ผักบุ้งไฟแดงสดกรอบ ผัดคลุกเคล้ากับกุ้งและปลาหมึกชิ้นโตในซอสเต้าเจี้ยวหอมรสเข้มข้น ดึงความหวานจากอาหารทะเลผสมผสานความกรอบของผักได้อย่างลงตัว เสิร์ฟพร้อมข้าวสวยร้อนๆ\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ผักบุ้งจีนสด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">กุ้งสด และ ปลาหมึก</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">พริกขี้หนูและกระเทียมบุบ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">เต้าเจี้ยวและซอสปรุงรส</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวย</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%9c%e0%b8%b1%e0%b8%81%e0%b8%9a%e0%b8%b8%e0%b9%89%e0%b8%87%e0%b8%97%e0%b8%b0%e0%b9%80%e0%b8%a5', '', '', '2026-01-16 01:54:05', '2026-01-15 18:54:05', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1336', 0, 'product', '', 0),
