(1368, 1, '2026-01-10 17:54:13', '2026-01-10 10:54:13', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">430 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดผักบุ้งหมูสับ', 'ผักบุ้งไฟแดงสดกรอบ ผัดคลุกเคล้ากับหมูนุ่มและเต้าเจี้ยวหอมๆ รสชาติเข้มข้นจัดจ้าน หอมกลิ่นกระทะและพริกกระเทียม เสิร์ฟพร้อมข้าวสวยร้อนๆ อร่อยสไตล์ไทยแท้ที่คุ้นเคย\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">ผักบุ้งจีนสด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">เนื้อหมู (ชิ้นหรือสับตามชอบ)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">พริกขี้หนูและกระเทียมบุบ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">เต้าเจี้ยวและซอสปรุงรส</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวย</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%9c%e0%b8%b1%e0%b8%81%e0%b8%9a%e0%b8%b8%e0%b9%89%e0%b8%87%e0%b8%ab%e0%b8%a1%e0%b8%b9%e0%b8%aa%e0%b8%b1%e0%b8%9a', '', '', '2026-01-16 01:50:33', '2026-01-15 18:50:33', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1368', 0, 'product', '', 0);
