(1369, 1, '2026-01-10 17:55:22', '2026-01-10 10:55:22', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">450 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>', 'ผัดกะหล่ำทะเล', 'กะหล่ำปลีสดผัดไฟแรงจนหวานกรอบ คลุกเคล้ากุ้งและปลาหมึกสดชิ้นโตในซอสรสกลมกล่อม หอมกลิ่นกระทะและสมุนไพรเบาๆ ทานคู่ข้าวสวยร้อนๆ อร่อยสดชื่นได้รสชาติจากทะเล\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">กะหล่ำปลีสด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">กุ้งสด และ ปลาหมึก</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">กระเทียมสับ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ซอสปรุงรส (น้ำมันหอย, ซีอิ๊วขาว)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวย</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%81%e0%b8%b0%e0%b8%ab%e0%b8%a5%e0%b9%88%e0%b8%b3%e0%b8%97%e0%b8%b0%e0%b9%80%e0%b8%a5', '', '', '2026-01-16 01:50:36', '2026-01-15 18:50:36', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1369', 0, 'product', '', 0),
(1370, 1, '2026-01-10 17:56:59', '2026-01-10 10:56:59', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">420 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่</span><span class=\"font-medium\">ข้าว</span></li>\r\n</ul>', 'ผัดใบกะหล่ำหมู', 'กะหล่ำปลีสดกรอบผัดไฟแรงจนหอมกลิ่นกระทะ คลุกเคล้าหมูนุ่มรสกลมกล่อม เสิร์ฟพร้อมข้าวสวยร้อนๆ เป็นเมนูที่ดึงความหวานธรรมชาติของผักออกมาได้อย่างดีเยี่ยม\r\n<strong>ส่วนผสม</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\">กะหล่ำปลีสด</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\">เนื้อหมู (สันนอกหรือสันคอ)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\">กระเทียมสับ</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,3,0\">ซอสปรุงรส (น้ำมันหอย, ซีอิ๊วขาว)</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,4,0\">ข้าวสวย</p>\r\n</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b9%83%e0%b8%9a%e0%b8%81%e0%b8%b0%e0%b8%ab%e0%b8%a5%e0%b9%88%e0%b8%b3%e0%b8%ab%e0%b8%a1%e0%b8%b9', '', '', '2026-01-16 01:48:03', '2026-01-15 18:48:03', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1370', 0, 'product', '', 0),
