(1412, 1, '2026-01-10 18:38:44', '2026-01-10 11:38:44', '<strong>ข้อมูลโภชนาการ\r\n</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">628 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\r\n</ul>\r\n<strong> </strong>', 'กะเพราหมูสับเต้าหู้ไข่', 'กะเพราหมูสับเต้าหู้สูตรบ้าน ๆ หอมกลิ่นใบกะเพราสด ผัดกับหมูสับเนื้อนุ่มและเต้าหู้ชิ้นพอดีคำ ปรุงรสจัดจ้านด้วยพริกกระเทียมและซอสสูตรเฉพาะ รสเผ็ดกำลังดี กลมกล่อม อิ่มอร่อย ได้ทั้งโปรตีนและความอร่อยในจานเดียว\r\n<strong>ส่วนผสม\r\n</strong>\r\n<ul>\r\n 	<li>หมูสับ</li>\r\n 	<li>ใบกระเพรา</li>\r\n 	<li>พริก</li>\r\n 	<li>กระเทียม</li>\r\n 	<li>ซอสหอยนางรม</li>\r\n 	<li>ซอสปรุงรส</li>\r\n 	<li>น้ำตาล</li>\r\n 	<li>เต้าหู้ไข่  หลอด</li>\r\n</ul>', 'publish', 'closed', 'closed', '', '%e0%b8%81%e0%b8%b0%e0%b9%80%e0%b8%9e%e0%b8%a3%e0%b8%b2%e0%b8%ab%e0%b8%a1%e0%b8%b9%e0%b8%aa%e0%b8%b1%e0%b8%9a%e0%b9%80%e0%b8%95%e0%b9%89%e0%b8%b2%e0%b8%ab%e0%b8%b9%e0%b9%89%e0%b9%84%e0%b8%82%e0%b9%88', '', '', '2026-01-15 21:48:38', '2026-01-15 14:48:38', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1412', 0, 'product', '', 0),
