(1414, 1, '2026-01-10 18:42:46', '2026-01-10 11:42:46', '<strong>ข้อมูลโภชนาการ</strong>\r\n<ul>\r\n 	<li><span class=\"gs_tkn\">50 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\r\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\r\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ แอดออน</span></li>\r\n</ul>', 'ไข่ดาว', 'ไข่ไก่สดทอดในน้ำมันร้อนๆ จนได้ขอบที่กรอบฟูและเนื้อสัมผัสที่แตกต่างกันตามระดับความสุก จะทานคู่กับเมนูผัด เมนูแกง หรือแค่เหยาะซอสปรุงรสอย่างเดียวก็อร่อยง่ายๆ ได้ใจความ\r\n<strong>ระดับความสุก\r\n</strong>\r\n<ul>\r\n 	<li>\r\n<p data-path-to-node=\"5,0,0\"><b data-path-to-node=\"5,0,0\" data-index-in-node=\"0\">ไข่ดาวไม่สุก (Sunny Side Up):</b> ไข่ขาวสุกนุ่ม ไข่แดงเยิ้มๆ เป็นลาวา</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,1,0\"><b data-path-to-node=\"5,1,0\" data-index-in-node=\"0\">ไข่ดาวสุกปานกลาง (Medium):</b> ไข่แดงหนึบเป็นยางมะตูม กำลังดี</p>\r\n</li>\r\n 	<li>\r\n<p data-path-to-node=\"5,2,0\"><b data-path-to-node=\"5,2,0\" data-index-in-node=\"0\">ไข่ดาวสุก (Well Done):</b> ไข่แดงสุกทั่ว แผ่นไข่กรอบหอม</p>\r\n</li>\r\n</ul>\r\n<strong> </strong>', 'publish', 'closed', 'closed', '', '%e0%b9%84%e0%b8%82%e0%b9%88%e0%b8%94%e0%b8%b2%e0%b8%a7', '', '', '2026-01-11 17:30:24', '2026-01-11 10:30:24', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?post_type=product&#038;p=1414', 0, 'product', '', 0),
