(1470, 1, '2026-01-12 21:30:00', '2026-01-12 14:30:00', '<strong>ข้อมูลโภชนาการ</strong>\n<ul>\n 	<li><span class=\"gs_tkn\">580 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่ อาหารจานเดียว</span></li>\n</ul>', 'กะเพราหมูสับหน่อไม้ดอง', '<p>กะเพราเนื้อหน่อไม้รสจัดจ้าน ใช้เนื้อวัวนุ่มผัดกับหน่อไม้กรอบหอม เพิ่มรสสัมผัสกรุบกรอบ ผัดกับพริกกระเทียมหอม ๆ ใส่ใบกะเพราสด ปรุงรสเข้มข้น เผ็ดกำลังดี อร่อยกลมกล่อม ทานกับข้าวสวยร้อน ๆ ลงตัว<br><strong>ส่วนผสม</strong></p><ul data-start=\"372\" data-end=\"480\"><li data-start=\"372\" data-end=\"384\"><p data-start=\"374\" data-end=\"384\">เนื้อวัว</p></li><li data-start=\"385\" data-end=\"396\"><p data-start=\"387\" data-end=\"396\">หน่อไม้</p></li><li data-start=\"397\" data-end=\"409\"><p data-start=\"399\" data-end=\"409\">ใบกะเพรา</p></li><li data-start=\"410\" data-end=\"418\"><p data-start=\"412\" data-end=\"418\">พริก</p></li><li data-start=\"419\" data-end=\"431\"><p data-start=\"421\" data-end=\"431\">กระเทียม</p></li><li data-start=\"432\" data-end=\"445\"><p data-start=\"434\" data-end=\"445\">ซอสปรุงรส</p></li><li data-start=\"446\" data-end=\"456\"><p data-start=\"448\" data-end=\"456\">น้ำปลา</p></li><li data-start=\"457\" data-end=\"470\"><p data-start=\"459\" data-end=\"470\">น้ำมันพืช</p></li><li data-start=\"471\" data-end=\"480\"><p data-start=\"473\" data-end=\"480\">ข้าวสวย</p></li></ul>', 'inherit', 'closed', 'closed', '', '1393-autosave-v1', '', '', '2026-01-12 21:30:00', '2026-01-12 14:30:00', '', 1393, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1470', 0, 'revision', '', 0),
