(1478, 1, '2026-01-11 18:58:57', '2026-01-11 11:58:57', '<strong>ข้อมูลโภชนาการ</strong>\n<ul>\n 	<li><span class=\"gs_tkn\">580 </span><span class=\"gs_tkn\">กิโลแคลอรี่</span></li>\n 	<li><span class=\"text-muted-foreground\">เวลาในการเตรียม</span><span class=\"font-medium\">10-15 นาที</span></li>\n 	<li class=\"flex justify-between\"><span class=\"text-muted-foreground\">หมวดหมู่</span><span class=\"font-medium\">ข้าวราดเเกง</span></li>\n</ul>', 'ผัดพริกเเกงไก่กรอบ', 'สัมผัสความกรุบกรอบของไก่ทอดสีเหลืองทองที่เคลือบด้วยซอสพริกแกงเผ็ดรสเข้มข้น ดึงกลิ่นหอมของสมุนไพรไทยออกมาได้อย่างเต็มที่ ทั้งความหอมจากผิวมะกรูดและพริกแกงตำสด รสชาติจัดจ้านถึงเครื่องสไตล์ไทยแท้ เสิร์ฟคู่กับข้าวสวยร้อน ๆ ที่ช่วยชูรสชาติให้กลมกล่อมยิ่งขึ้นในทุกคำ\n<strong>ส่วนผสม</strong>\n<ul>\n 	<li>\n<p data-path-to-node=\"6,0,0\">เนื้อไก่ส่วนสะโพกหรืออก (ชุบแป้งทอดกรอบ)</p>\n</li>\n 	<li>\n<p data-path-to-node=\"6,1,0\">พริกแกงเผ็ด</p>\n</li>\n 	<li>\n<p data-path-to-node=\"6,2,0\">ถั่วฝักยาว</p>\n</li>\n 	<li>\n<p data-path-to-node=\"6,3,0\">ใบมะกรูดฉีก</p>\n</li>\n 	<li>\n<p data-path-to-node=\"6,4,0\">พริกชี้ฟ้าแดง</p>\n</li>\n 	<li>\n<p data-path-to-node=\"6,5,0\">เครื่องปรุงรส (น้ำปลา, น้ำตาลปี๊บ)</p>\n</li>\n</ul>', 'inherit', 'closed', 'closed', '', '1373-autosave-v1', '', '', '2026-01-11 18:58:57', '2026-01-11 11:58:57', '', 1373, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1478', 0, 'revision', '', 0),
