(1485, 1, '2026-01-11 19:53:10', '2026-01-11 12:53:10', '<img width=\"1024\" height=\"1024\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/สุกี้น้ำทะเล-1.jpg\" alt=\"\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/สุกี้น้ำทะเล-1.jpg 1024w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/สุกี้น้ำทะเล-1-300x300.jpg 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/สุกี้น้ำทะเล-1-150x150.jpg 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/สุกี้น้ำทะเล-1-768x768.jpg 768w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />																<h2>สุกี้น้ำทะเล</h2>		<p>ยกขบวนกุ้งและปลาหมึกสดในน้ำซุปรสกลมกล่อม พร้อมวุ้นเส้นเหนียวนุ่มและผักสดนานาชนิด เสิร์ฟคู่ซอสสุกี้รสเด็ด อร่อยสดชื่นได้รสชาติทะเลแท้ๆ สารอาหารครบถ้วนในถ้วยเดียว</p>					\n						<details id=\"e-n-accordion-item-1910\" open>\n				<summary data-accordion-index=\"1\" tabindex=\"0\" aria-expanded=\"true\" aria-controls=\"e-n-accordion-item-1910\" >\n					 ส่วนผสม \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li><p data-path-to-node=\"5,0,0\">กุ้งสด และ ปลาหมึก</p></li><li><p data-path-to-node=\"5,1,0\">วุ้นเส้นสด</p></li><li><p data-path-to-node=\"5,2,0\">ผักกาดขาวและผักบุ้ง</p></li><li><p data-path-to-node=\"5,3,0\">ไข่ไก่</p></li><li><p data-path-to-node=\"5,4,0\">ซอสสุกี้สูตรพิเศษ</p></li><li><p data-path-to-node=\"5,5,0\">น้ำซุปใสกลมกล่อม</p></li></ul>								\n					</details>\n						<details id=\"e-n-accordion-item-1911\" >\n				<summary data-accordion-index=\"2\" tabindex=\"-1\" aria-expanded=\"false\" aria-controls=\"e-n-accordion-item-1911\" >\n					 ข้อมูลโภชนาการ \n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h384c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n			<svg aria-hidden=\"true\" viewBox=\"0 0 448 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M416 208H272V64c0-17.67-14.33-32-32-32h-32c-17.67 0-32 14.33-32 32v144H32c-17.67 0-32 14.33-32 32v32c0 17.67 14.33 32 32 32h144v144c0 17.67 14.33 32 32 32h32c17.67 0 32-14.33 32-32V304h144c17.67 0 32-14.33 32-32v-32c0-17.67-14.33-32-32-32z\"></path></svg>\n						</summary>\n									<ul><li>450 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>								\n					</details>\n				<ul><li><p data-path-to-node=\"5,0,0\">กุ้งสด และ ปลาหมึก</p></li><li><p data-path-to-node=\"5,1,0\">วุ้นเส้นสด</p></li><li><p data-path-to-node=\"5,2,0\">ผักกาดขาวและผักบุ้ง</p></li><li><p data-path-to-node=\"5,3,0\">ไข่ไก่</p></li><li><p data-path-to-node=\"5,4,0\">ซอสสุกี้สูตรพิเศษ</p></li><li><p data-path-to-node=\"5,5,0\">น้ำซุปใสกลมกล่อม</p></li></ul><ul><li>450 กิโลแคลอรี่</li><li>เวลาในการเตรียม10-15 นาที</li><li>หมวดหมู่ข้าว</li></ul>					\n			บาท			\n				30', 'สุกี้น้ำทะเล', '', 'inherit', 'closed', 'closed', '', '741-autosave-v1', '', '', '2026-01-11 19:53:10', '2026-01-11 12:53:10', '', 741, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1485', 0, 'revision', '', 0),
