2.28-32.19 0-44.48L242.72 256z\"></path></svg>						\n										สั่งอาหาร\n											</a>\n									</li>\n								<li>\n											<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%95%e0%b8%b0%e0%b8%81%e0%b8%a3%e0%b9%89%e0%b8%b2/\">\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M256 8C119.033 8 8 119.033 8 256s111.033 248 248 248 248-111.033 248-248S392.967 8 256 8zm80 248c0 44.112-35.888 80-80 80s-80-35.888-80-80 35.888-80 80-80 80 35.888 80 80z\"></path></svg>						\n										ตะกร้าของฉัน\n											</a>\n									</li>\n						</ul>', 'หน้าเเรก', '', 'inherit', 'closed', 'closed', '', '29-revision-v1', '', '', '2026-01-13 10:18:22', '2026-01-13 03:18:22', '', 29, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1503', 0, 'revision', '', 0);
