(1563, 1, '2026-01-15 21:08:25', '2026-01-15 14:08:25', '{\n    \"astra-settings[archive-product-ast-content-layout]\": {\n        \"value\": \"default\",\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-01-15 14:02:50\"\n    },\n    \"astra-settings[shop-product-align-responsive]\": {\n        \"value\": {\n            \"desktop\": \"align-left\",\n            \"tablet\": \"align-left\",\n            \"mobile\": \"align-left\"\n        },\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-01-15 14:02:50\"\n    },\n    \"astra-settings[shop-style]\": {\n        \"value\": \"shop-page-modern-style\",\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-01-15 14:02:50\"\n    },\n    \"astra-settings[shop-no-of-products]\": {\n        \"value\": 12,\n        \"type\": \"option\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-01-15 14:02:50\"\n    },\n    \"custom_css[astra]\": {\n        \"value\": \"/* \\u0e1b\\u0e38\\u0e48\\u0e21\\u0e2b\\u0e22\\u0e34\\u0e1a\\u0e43\\u0e2a\\u0e48\\u0e15\\u0e30\\u0e01\\u0e23\\u0e49\\u0e32 */\\n.woocommerce a.button,\\n.woocommerce button.button,\\n.woocommerce input.button {\\n    background-color: #e63946 !important; /* \\u0e2a\\u0e35\\u0e1b\\u0e38\\u0e48\\u0e21 */\\n    color: #ffffff !important;           /* \\u0e2a\\u0e35\\u0e15\\u0e31\\u0e27\\u0e2d\\u0e31\\u0e01\\u0e29\\u0e23 */\\n    border-radius: 12px;                 /* \\u0e02\\u0e2d\\u0e1a\\u0e21\\u0e19 */\\n    padding: 12px 20px;\\n    font-weight: bold;\\n}\\n\\n/* \\u0e15\\u0e2d\\u0e19\\u0e40\\u0e2d\\u0e32\\u0e40\\u0e21\\u0e32\\u0e2a\\u0e4c\\u0e0a\\u0e35\\u0e49 */\\n.woocommerce a.button:hover,\\n.woocommerce button.button:hover {\\n    background-color: #c1121f !important;\\n}\\n/* \\u0e01\\u0e23\\u0e2d\\u0e1a\\u0e40\\u0e25\\u0e02\\u0e2b\\u0e19\\u0e49\\u0e32 */\\n.woocommerce nav.woocommerce-pagination ul li a,\\n.woocommerce nav.woocommerce-pagination ul li span {\\n    border: 1px solid #e63946;   /* \\u0e2a\\u0e35\\u0e02\\u0e2d\\u0e1a */\\n    color: #e63946;              /* \\u0e2a\\u0e35\\u0e15\\u0e31\\u0e27\\u0e40\\u0e25\\u0e02 */\\n    padding: 10px 14px;\\n    margin: 0 4px;\\n    border-radius: 8px;\\n    font-weight: bold;\\n}\\n\\n/* \\u0e40\\u0e25\\u0e02\\u0e2b\\u0e19\\u0e49\\u0e32\\u0e1b\\u0e31\\u0e08\\u0e08\\u0e38\\u0e1a\\u0e31\\u0e19 (\\u0e40\\u0e0a\\u0e48\\u0e19 1) */\\n.woocommerce nav.woocommerce-pagination ul li span.current {\\n    background-color: #e63946;   /* \\u0e2a\\u0e35\\u0e1e\\u0e37\\u0e49\\u0e19 */\\n    color: #ffffff;              /* \\u0e2a\\u0e35\\u0e15\\u0e31\\u0e27\\u0e40\\u0e25\\u0e02 */\\n    border-color: #e63946;\\n}\\n\\n/* \\u0e15\\u0e2d\\u0e19\\u0e40\\u0e2d\\u0e32\\u0e40\\u0e21\\u0e32\\u0e2a\\u0e4c\\u0e0a\\u0e35\\u0e49 */\\n.woocommerce nav.woocommerce-pagination ul li a:hover {\\n    background-color: #e63946;\\n    color: #ffffff;\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-01-15 14:08:25\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '9d000169-921e-48c7-8488-0e1d75cb7aa0', '', '', '2026-01-15 21:08:25', '2026-01-15 14:08:25', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1563', 0, 'customize_changeset', '', 0),
(1564, 1, '2026-01-15 21:08:25', '2026-01-15 14:08:25', '/* ปุ่มหยิบใส่ตะกร้า */\n.woocommerce a.button,\n.woocommerce button.button,\n.woocommerce input.button {\n    background-color: #e63946 !important; /* สีปุ่ม */\n    color: #ffffff !important;           /* สีตัวอักษร */\n    border-radius: 12px;                 /* ขอบมน */\n    padding: 12px 20px;\n    font-weight: bold;\n}\n\n/* ตอนเอาเมาส์ชี้ */\n.woocommerce a.button:hover,\n.woocommerce button.button:hover {\n    background-color: #c1121f !important;\n}\n/* กรอบเลขหน้า */\n.woocommerce nav.woocommerce-pagination ul li a,\n.woocommerce nav.woocommerce-pagination ul li span {\n    border: 1px solid #e63946;   /* สีขอบ */\n    color: #e63946;              /* สีตัวเลข */\n    padding: 10px 14px;\n    margin: 0 4px;\n    border-radius: 8px;\n    font-weight: bold;\n}\n\n/* เลขหน้าปัจจุบัน (เช่น 1) */\n.woocommerce nav.woocommerce-pagination ul li span.current {\n    background-color: #e63946;   /* สีพื้น */\n    color: #ffffff;              /* สีตัวเลข */\n    border-color: #e63946;\n}\n\n/* ตอนเอาเมาส์ชี้ */\n.woocommerce nav.woocommerce-pagination ul li a:hover {\n    background-color: #e63946;\n    color: #ffffff;\n}\n/* การ์ดสินค้า */\n.woocommerce ul.products li.product {\n    background: #ffffff;\n    border-radius: 18px;\n    padding: 16px;\n    transition: \n        transform 0.35s ease,\n        box-shadow 0.35s ease;\n    box-shadow: 0 6px 18px rgba(0,0,0,0.06);\n}\n\n/* ตอน hover */\n.woocommerce ul.products li.product:hover {\n    transform: translateY(-10px);\n    box-shadow: 0 24px 50px rgba(0,0,0,0.14);\n}\n/* กล่อง pagination ทั้งหมด */\n.woocommerce nav.woocommerce-pagination ul {\n    border: none;\n    display: flex;\n    gap: 10px;\n}\n\n/* ปุ่มเลขหน้า */\n.woocommerce nav.woocommerce-pagination ul li a,\n.woocommerce nav.woocommerce-pagination ul li span {\n    border: none !important;              /* ตัดกรอบเหลี่ยม */\n    background: #ffffff;\n    color: #e63946;\n    padding: 10px 16px;\n    border-radius: 999px;                 /* กลมมน */\n    font-weight: 600;\n    box-shadow: 0 6px 14px rgba(0,0,0,0.08);\n    transition: all 0.3s ease;\n}\n\n/* เลขหน้าปัจจุบัน */\n.woocommerce nav.woocommerce-pagination ul li span.current {\n    background: #e63946;\n    color: #ffffff;\n    box-shadow: 0 10px 24px rgba(230,57,70,0.35);\n}\n\n/* hover */\n.woocommerce nav.woocommerce-pagination ul li a:hover {\n    background: #e63946;\n    color: #ffffff;\n    transform: translateY(-3px);\n}\n/* เปลี่ยนสีชื่อสินค้าในตะกร้า */\n.woocommerce-cart .product-name a {\n    color: #e63946; /* เปลี่ยนเป็นสีที่ต้องการ */\n    font-weight: 600;\n}\n\n/* hover ตอนเอาเมาส์ชี้ */\n.woocommerce-cart .product-name a:hover {\n    color: #000000;\n}\n/* กล่องแจ้งเตือนเพิ่มสินค้าลงตะกร้า */\n.woocommerce-message {\n    border-color: #2ecc71;              /* เส้นขอบสีเขียว */\n    background-color: #eafaf1;           /* พื้นหลังเขียวอ่อน */\n    color: #1e8449;                      /* ตัวอักษรเขียวเข้ม */\n}\n\n/* ไอคอน ✓ ด้านหน้า */\n.woocommerce-message::before {\n    color: #2ecc71;                      /* ไอคอนสีเขียว */\n}\n\n/* ปุ่ม \"ดูตะกร้าสินค้า\" */\n.woocommerce-message .button {\n    background-color: #2ecc71;\n    color: #ffffff;\n    border-radius: 8px;\n}\n\n.woocommerce-message .button:hover {\n    background-color: #27ae60;\n}\n\n\n', 'astra', '', 'publish', 'closed', 'closed', '', 'astra', '', '', '2026-01-15 21:53:56', '2026-01-15 14:53:56', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/astra/', 0, 'custom_css', '', 0),
