n    color: #ffffff;\\n}\\n.woocommerce ul.products li.product img {\\n    border-radius: 16px;\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.08);\\n}\\n/* \\u0e23\\u0e39\\u0e1b\\u0e2a\\u0e34\\u0e19\\u0e04\\u0e49\\u0e32 */\\n.woocommerce ul.products li.product img {\\n    border-radius: 16px;                 /* \\u0e21\\u0e38\\u0e21\\u0e42\\u0e04\\u0e49\\u0e07 */\\n    transition: all 0.3s ease;           /* \\u0e04\\u0e27\\u0e32\\u0e21\\u0e19\\u0e38\\u0e48\\u0e21\\u0e02\\u0e2d\\u0e07\\u0e41\\u0e2d\\u0e19\\u0e34\\u0e40\\u0e21\\u0e0a\\u0e31\\u0e19 */\\n    box-shadow: 0 6px 14px rgba(0,0,0,0.08);\\n}\\n\\n/* \\u0e15\\u0e2d\\u0e19\\u0e40\\u0e2d\\u0e32\\u0e40\\u0e21\\u0e32\\u0e2a\\u0e4c\\u0e0a\\u0e35\\u0e49 */\\n.woocommerce ul.products li.product:hover img {\\n    transform: translateY(-10px);        /* \\u0e25\\u0e2d\\u0e22\\u0e02\\u0e36\\u0e49\\u0e19 */\\n    box-shadow: 0 14px 30px rgba(0,0,0,0.15);\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-01-15 14:10:51\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'f07a5023-184b-4b5b-9c90-b8045d3992ae', '', '', '2026-01-15 21:10:51', '2026-01-15 14:10:51', '', 0, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1566', 0, 'customize_changeset', '', 0),
