.1 33.9 14.1H224c17.7 0 32-14.3 32-32s-14.3-32-32-32zM64 128c26.5 0 48-21.5 48-48S90.5 32 64 32 16 53.5 16 80s21.5 48 48 48zm224-96l31.5 223.1-30.9 154.6c-4.3 21.6 13 38.3 31.4 38.3 15.2 0 28-9.1 32.3-30.4.9 16.9 14.6 30.4 31.7 30.4 17.7 0 32-14.3 32-32 0 17.7 14.3 32 32 32s32-14.3 32-32V0H288v32zm-96 0v160h64V0h-32c-17.7 0-32 14.3-32 32zM544 0h-32v496c0 8.8 7.2 16 16 16h32c8.8 0 16-7.2 16-16V32c0-17.7-14.3-32-32-32z\"></path></svg>						\n										บัญชีของฉัน\n											</a>\n									</li>\n						</ul>', 'หน้าเเรก', '', 'inherit', 'closed', 'closed', '', '29-revision-v1', '', '', '2026-01-15 23:40:32', '2026-01-15 16:40:32', '', 29, 'http://digiproj.sut.ac.th/wp07/wordpress/?p=1634', 0, 'revision', '', 0);
