INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1710, 1, '2026-01-16 08:30:58', '2026-01-16 01:30:58', '<figure><img src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2026/01/Banner-3.png\" alt=\"Banner-3\" /></figure>			\n							<h2>อาหารอร่อย</h2>					<h2>ร้อนๆ จ้า! พึ่งขึ้นจากเตา หอมฉุยเลย!</h2>		<p>สั่งอาหารตามสั่งแสนอร่อยจากครัว ปรุงสดใหม่ทุกออเดอร์ ไม่ว่าคุณจะหิวเวลาไหน เราพร้อมเสิร์ฟความอร่อยตรงหน้า ขอเชิญเลือกเมนูโปรดของคุณ แล้วปล่อยให้เราดูแลมื้อพิเศษนี้ ด้วยอาหารที่ปรุงสดใหม่ หอม น่ารับประทาน และพร้อมส่งมอบความสุขถึงมือคุณ</p>								<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%a3%e0%b9%89%e0%b8%b2%e0%b8%99%e0%b8%84%e0%b9%89%e0%b8%b2/\">\n									สั่งซื้อทันที!\n					</a>\n						https://youtu.be/B1fahnxx_Qo[fibosearch]			<h2>เมนูเเนะนำของทางร้าน</h2>		<p>บริการด้วยใจ อาหารอร่อย ส่งตรงถึงมือคุณอย่างปลอดภัย</p>		\n			<article>\n					<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%81%e0%b8%b0%e0%b9%80%e0%b8%9e%e0%b8%a3%e0%b8%b2/\" rel=\"bookmark\">\n						<img width=\"300\" height=\"300\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-300x300.webp\" alt=\"หมูกรอบทอดกระเทียม\" loading=\"lazy\" decoding=\"async\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-300x300.webp 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-100x100.webp 100w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-600x600.webp 600w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-64x64.webp 64w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-150x150.webp 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1-768x768.webp 768w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/หมูกรอบทอดกระเทียม-1.webp 1024w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" />					</a>\n									<h3>\n						<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%81%e0%b8%b0%e0%b9%80%e0%b8%9e%e0%b8%a3%e0%b8%b2/\" rel=\"bookmark\">\n							หมูกรอบทอดกระเทียม						</a>\n					</h3>\n									<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%82%e0%b9%89%e0%b8%b2%e0%b8%a7%e0%b8%9c%e0%b8%b1%e0%b8%94%e0%b8%81%e0%b8%b0%e0%b9%80%e0%b8%9e%e0%b8%a3%e0%b8%b2/\" rel=\"bookmark\">\n						ดูรายลละเอียดเพื่อสั่งอาหาร →					</a>\n		</article>\n				<article>\n					<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%95%e0%b9%89%e0%b8%a1%e0%b8%a2%e0%b8%b3%e0%b8%81%e0%b8%b8%e0%b9%89%e0%b8%87/\" rel=\"bookmark\">\n						<img width=\"300\" height=\"300\" src=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-300x300.webp\" alt=\"หมูกรอบสามรส\" loading=\"lazy\" decoding=\"async\" srcset=\"http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-300x300.webp 300w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-100x100.webp 100w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-600x600.webp 600w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-64x64.webp 64w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-150x150.webp 150w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1-768x768.webp 768w, http://digiproj.sut.ac.th/wp07/wordpress/wp-content/uploads/2025/11/OIP-4-1.webp 1024w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" />					</a>\n									<h3>\n						<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%95%e0%b9%89%e0%b8%a1%e0%b8%a2%e0%b8%b3%e0%b8%81%e0%b8%b8%e0%b9%89%e0%b8%87/\" rel=\"bookmark\">\n							หมูกรอบสามรส						</a>\n					</h3>\n									<a href=\"http://digiproj.sut.ac.th/wp07/wordpress/%e0%b8%95%e0%b9%89%e0%b8%a1%e0%b8%a2%e0%b8%b3%e0